   0 export class Result<T, E = Error> {
   1   public readonly isSuccess: boolean;
   2   public readonly isFailure: boolean;
   3   public readonly error: E | null;
   4   private readonly _value: T | null;
   5 
   6   private constructor(isSuccess: boolean, error?: E, value?: T) {
   7     if (isSuccess && error) {
   8       throw new Error("InvalidOperation: A result cannot be successful and contain an error");
   9     }
  10     if (!isSuccess && !error) {
  11       throw new Error("InvalidOperation: A failing result must contain an error");
  12     }
  13 
  14     this.isSuccess = isSuccess;
  15     this.isFailure = !isSuccess;
  16     this.error = error || null;
  17     this._value = value !== undefined ? value : null;
  18 
  19     Object.freeze(this);
  20   }
  21 
  22   public getValue(): T {
  23     if (!this.isSuccess) {
  24       throw new Error("Can't get the value of an error result. Use 'errorValue' instead.");
  25     }
  26     return this._value as T;
  27   }
  28 
  29   public static ok<T, E>(value?: T): Result<T, E> {
  30     return new Result<T, E>(true, undefined, value);
  31   }
  32 
  33   public static fail<T, E>(error: E): Result<T, E> {
  34     // Note: We don't log here automatically to avoid noise from handled validation errors.
  35     // Use Telemetry.logFailure manually in repositories/controllers for critical errors.
  36     return new Result<T, E>(false, error);
  37   }
  38 
  39   public static combine(results: Result<any, any>[]): Result<any, any> {
  40     for (const result of results) {
  41       if (result.isFailure) return result;
  42     }
  43     return Result.ok();
  44   }
  45 }
