   0 import { NextResponse } from 'next/server';
   1 import { handleApiError, handleUserResult } from '@/infrastructure/api/api-utils';
   2 import { container } from '@/infrastructure/di/container';
   3 import { UserController } from '@/modules/users/adapters/controllers/UserController';
   4 import { z } from 'zod';
   5 import { rateLimiter } from '@/infrastructure/security/rate-limiter';
   6 import { headers as nextHeaders } from 'next/headers';
   7 
   8 const loginSchema = z.object({
   9     email: z.string().email("Invalid email address"),
  10     password: z.string().min(1, "Password is required"),
  11     rememberMe: z.boolean().optional(),
  12     fingerprint: z.string().optional(),
  13     fingerprintData: z.any().optional(),
  14 });
  15 
  16 export async function POST(request: Request) {
  17   try {
  18     // 1. Rate Limiting
  19     const headersList = await nextHeaders();
  20     const ip = headersList.get('x-forwarded-for') || '127.0.0.1';
  21     const { allowed, resetAt } = await rateLimiter.check('login', ip, 5, 15 * 60 * 1000); // 5 attempts per 15 mins
  22 
  23     if (!allowed) {
  24         return NextResponse.json({ 
  25             error: "Too many login attempts. Please try again later.",
  26             resetAt 
  27         }, { status: 429 });
  28     }
  29 
  30     const body = await request.json();
  31     const validation = loginSchema.safeParse(body);
  32     
  33     if (!validation.success) {
  34         return handleApiError(validation.error);
  35     }
  36 
  37     const { email, password, rememberMe, fingerprint, fingerprintData } = validation.data;
  38     const controller = container.resolve(UserController);
  39     
  40     const result = await controller.login(email, password);
  41 
  42     if (result.isFailure) {
  43         return handleUserResult(result);
  44     }
  45 
  46     const loginData = result.getValue();
  47     const user = loginData.user;
  48 
  49     // --- 2FA Challenge Check ---
  50     const userProfileResult = await controller.getUser(user.uid);
  51     const userProfile = userProfileResult.isSuccess ? userProfileResult.getValue() : null;
  52 
  53     if (userProfile?.isTwoFactorEnabled) {
  54         return NextResponse.json({ 
  55             status: 'requires_2fa',
  56             userId: user.uid
  57         }, { status: 200 });
  58     }
  59 
  60     const token = loginData.token;
  61 
  62     // 2. Record Login History
  63     await controller.recordLogin({
  64         userId: user.uid,
  65         ip,
  66         userAgent: headersList.get('user-agent') || 'unknown',
  67         fingerprint: fingerprint || null
  68     });
  69 
  70     // 3. Register Fingerprint if provided
  71     if (fingerprint && fingerprintData) {
  72         await controller.registerFingerprint(user.uid, fingerprint, fingerprintData);
  73     }
  74 
  75     // 30 days if remember me, otherwise 5 days
  76     const expiresIn = rememberMe 
  77         ? 60 * 60 * 24 * 30 * 1000 
  78         : 60 * 60 * 24 * 5 * 1000;
  79 
  80     const response = NextResponse.json({ 
  81         status: 'success',
  82         user
  83     }, { status: 200 });
  84 
  85     response.cookies.set({
  86       name: '__session',
  87       value: token,
  88       maxAge: expiresIn / 1000,
  89       httpOnly: true,
  90       secure: process.env.NODE_ENV === 'production',
  91       sameSite: 'lax',
  92       path: '/',
  93     });
  94 
  95     return response;
  96   } catch (error) {
  97     return handleApiError(error);
  98   }
  99 }
