   0 import { injectable } from "tsyringe";
   1 import { db } from "@/infrastructure/db";
   2 import { features } from "@/infrastructure/db/schema";
   3 import { IFeatureRepository } from "../../domain/repositories/IFeatureRepository";
   4 import { Feature } from "../../domain/entities/Feature";
   5 import { eq } from "drizzle-orm";
   6 
   7 @injectable()
   8 export class SQLiteFeatureRepository implements IFeatureRepository {
   9     async getAll(): Promise<Feature[]> {
  10         const results = await db.query.features.findMany();
  11         return results.map(this.toDomain);
  12     }
  13 
  14     async getById(id: string): Promise<Feature | null> {
  15         const result = await db.query.features.findFirst({
  16             where: eq(features.id, id),
  17         });
  18         return result ? this.toDomain(result) : null;
  19     }
  20 
  21     async update(id: string, data: Partial<Feature>): Promise<Feature> {
  22         const updatedAt = new Date().toISOString();
  23         const persistenceData = this.toPersistencePartial({ ...data, updatedAt });
  24         await db.update(features)
  25             .set(persistenceData)
  26             .where(eq(features.id, id));
  27         
  28         const updated = await this.getById(id);
  29         if (!updated) throw new Error(`Feature ${id} not found after update`);
  30         return updated;
  31     }
  32 
  33     private toDomain(result: any): Feature {
  34         return {
  35             ...result,
  36             isEnabled: !!result.isEnabled,
  37         };
  38     }
  39 
  40     private toPersistencePartial(data: Partial<Feature>): any {
  41         const persistence: any = { ...data };
  42         if (data.isEnabled !== undefined) {
  43             persistence.isEnabled = data.isEnabled ? 1 : 0;
  44         }
  45         return persistence;
  46     }
  47 }
  48 
